import { getContext, setContext } from 'svelte';

import type { TableVariant } from './table.types';

const TABLE_CONTEXT = Symbol('pdfcn-forme-table');
const TABLE_SECTION_CONTEXT = Symbol('pdfcn-forme-table-section');
const TABLE_ROW_CONTEXT = Symbol('pdfcn-forme-table-row');

export interface TableContext {
	readonly variant: TableVariant;
	readonly zebraStripe: boolean;
}

export interface TableSectionContext {
	readonly kind: 'header' | 'body' | 'footer';
	registerRow(): number;
}

export interface TableRowContext {
	readonly variant: TableVariant;
	readonly header: boolean;
	readonly footer: boolean;
	/** Returns this cell's zero-based position within the row. */
	registerCell(): number;
}

export const provideTableContext = (context: TableContext): void => {
	setContext(TABLE_CONTEXT, context);
};

export const useTableContext = (): TableContext | undefined =>
	getContext<TableContext | undefined>(TABLE_CONTEXT);

export const provideTableSectionContext = (context: TableSectionContext): void => {
	setContext(TABLE_SECTION_CONTEXT, context);
};

export const useTableSectionContext = (): TableSectionContext | undefined =>
	getContext<TableSectionContext | undefined>(TABLE_SECTION_CONTEXT);

export const provideTableRowContext = (context: TableRowContext): void => {
	setContext(TABLE_ROW_CONTEXT, context);
};

export const useTableRowContext = (): TableRowContext | undefined =>
	getContext<TableRowContext | undefined>(TABLE_ROW_CONTEXT);

import type { Style } from '$lib/types/pdf-components';
import type { PdfcnTheme } from '$lib/types/pdf-themes';

export type TableStyles = Record<string, Style>;

/** Creates all table styles from the active pdfcn theme. */
export const createTableStyles = (t: PdfcnTheme): TableStyles => {
	const { spacing, borderRadius, fontWeights, typography } = t.primitives;
	const borderColor = t.colors.border;
	const hairline = 0.5;
	const rule = 1;
	const thick = 1.5;
	const cellPadV = spacing[2] - 2;
	const cellPadH = spacing[2] + 2;
	const cellPadVCompact = spacing[0.5];
	const cellPadHCompact = spacing[2];
	const rowDivider: Style = {
		borderBottomColor: borderColor,
		borderBottomStyle: 'solid',
		borderBottomWidth: hairline
	};

	return {
		cell: {
			flex: 1,
			justifyContent: 'center',
			paddingHorizontal: cellPadH,
			paddingVertical: cellPadV
		},
		cellBordered: { paddingHorizontal: cellPadH, paddingVertical: cellPadV },
		cellBorderedBorder: {
			borderLeftColor: borderColor,
			borderLeftStyle: 'solid',
			borderLeftWidth: hairline
		},
		cellCompact: {
			paddingHorizontal: cellPadHCompact,
			paddingVertical: cellPadVCompact
		},
		cellFixed: {
			flexGrow: 0,
			flexShrink: 0,
			justifyContent: 'center',
			paddingHorizontal: cellPadH,
			paddingVertical: cellPadV
		},
		cellGridBorder: {
			borderLeftColor: borderColor,
			borderLeftStyle: 'solid',
			borderLeftWidth: hairline
		},
		cellMinimal: {
			paddingHorizontal: spacing[2] - 2,
			paddingVertical: spacing[1] + 1
		},
		cellPrimaryHeader: { paddingHorizontal: cellPadH, paddingVertical: cellPadV },
		cellStriped: { paddingHorizontal: cellPadH, paddingVertical: cellPadV },
		cellText: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			lineHeight: 1.2
		},
		cellTextCompact: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: typography.xs,
			lineHeight: 1.2
		},
		cellTextFooter: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.semibold,
			lineHeight: 1.2
		},
		cellTextHeaderBordered: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.bold,
			lineHeight: 1.2
		},
		cellTextHeaderCompact: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: typography.xs,
			fontWeight: fontWeights.semibold,
			letterSpacing: 0.6,
			lineHeight: 1.2,
			textTransform: 'uppercase'
		},
		cellTextHeaderGrid: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.semibold,
			lineHeight: 1.2
		},
		cellTextHeaderLine: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.semibold,
			lineHeight: 1.2
		},
		cellTextHeaderMinimal: {
			color: t.colors.mutedForeground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.medium,
			lineHeight: 1.2
		},
		cellTextHeaderPrimaryHeader: {
			color: t.colors.primaryForeground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: typography.xs,
			fontWeight: fontWeights.semibold,
			letterSpacing: 0.6,
			lineHeight: 1.2,
			textTransform: 'uppercase'
		},
		cellTextHeaderStriped: {
			color: t.colors.foreground,
			fontFamily: t.typography.body.fontFamily,
			fontSize: t.typography.body.fontSize,
			fontWeight: fontWeights.semibold,
			lineHeight: 1.2
		},
		row: { display: 'flex', flexDirection: 'row' },
		rowBordered: rowDivider,
		rowCompact: rowDivider,
		rowFooter: {
			borderTopColor: borderColor,
			borderTopStyle: 'solid',
			borderTopWidth: rule
		},
		rowFooterStriped: {
			backgroundColor: t.colors.muted,
			borderTopColor: borderColor,
			borderTopStyle: 'solid',
			borderTopWidth: rule
		},
		rowGrid: rowDivider,
		rowHeaderBordered: {
			backgroundColor: t.colors.muted,
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: hairline
		},
		rowHeaderCompact: {
			backgroundColor: t.colors.muted,
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: rule
		},
		rowHeaderGrid: {
			backgroundColor: t.colors.muted,
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: rule
		},
		rowHeaderLine: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: rule
		},
		rowHeaderMinimal: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: rule
		},
		rowHeaderPrimaryHeader: { backgroundColor: t.colors.primary },
		rowHeaderStriped: {
			backgroundColor: t.colors.muted,
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: rule
		},
		rowLine: rowDivider,
		rowMinimal: rowDivider,
		rowPrimaryHeader: rowDivider,
		rowStripe: { backgroundColor: t.colors.muted },
		rowStriped: {},
		table: {
			display: 'flex',
			flexDirection: 'column',
			marginBottom: t.spacing.componentGap,
			width: '100%'
		},
		tableBordered: {
			borderBottomLeftRadius: borderRadius.sm,
			borderBottomRightRadius: borderRadius.sm,
			borderColor,
			borderStyle: 'solid',
			borderTopLeftRadius: borderRadius.sm,
			borderTopRightRadius: borderRadius.sm,
			borderWidth: rule,
			overflow: 'hidden'
		},
		tableCompact: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: hairline
		},
		tableGrid: {
			borderBottomLeftRadius: borderRadius.md,
			borderBottomRightRadius: borderRadius.md,
			borderColor,
			borderStyle: 'solid',
			borderTopLeftRadius: borderRadius.md,
			borderTopRightRadius: borderRadius.md,
			borderWidth: thick,
			overflow: 'hidden'
		},
		tableLine: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: hairline
		},
		tableMinimal: { paddingVertical: spacing[2] },
		tablePrimaryHeader: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: hairline
		},
		tableStriped: {
			borderBottomColor: borderColor,
			borderBottomStyle: 'solid',
			borderBottomWidth: hairline,
			borderTopColor: borderColor,
			borderTopStyle: 'solid',
			borderTopWidth: hairline
		}
	};
};

import type { PDFComponentProps } from '$lib/types/pdf-components';

/** Table visual style variant. */
export type TableVariant =
	| 'line'
	| 'grid'
	| 'minimal'
	| 'striped'
	| 'compact'
	| 'bordered'
	| 'primary-header';

export interface TableProps extends PDFComponentProps {
	/** @default 'line' */
	variant?: TableVariant;
	/** @default false */
	zebraStripe?: boolean;
	/** @default false */
	noWrap?: boolean;
}

export type TableSectionProps = PDFComponentProps;

export interface TableRowProps extends PDFComponentProps {
	header?: boolean;
	footer?: boolean;
	stripe?: boolean;
	variant?: TableVariant;
}

export interface TableCellProps extends PDFComponentProps {
	header?: boolean;
	footer?: boolean;
	align?: 'left' | 'center' | 'right';
	width?: string | number;
	variant?: TableVariant;
	/**
	 * @deprecated Internal dividers are inferred from the cell's row position.
	 * Retained for source compatibility with upstream pdfcn call sites.
	 */
	_last?: boolean;
	/**
	 * Styled plain-text content. Use `children` for arbitrary component content.
	 */
	text?: string | number;
}
